using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using BeamScheduleFormatter;
class AppearanceUiTests {
 static int checks;static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
 [STAThread]static void Main(){string dir=Path.Combine(Path.GetTempPath(),"DTCE-Appearance-UI-"+Guid.NewGuid().ToString("N"));DesktopAppearance.StoragePath=Path.Combine(dir,"Appearance.xml");bool systemLight=true;DesktopAppearance.ReadSystemLight=()=>systemLight;Application.EnableVisualStyles();ModernUi.Install();AccessCodes.Granted=true;try{
  using(var f=new Form{Width=900,Height=600}){var grid=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false};grid.Columns.Add("ID","Member ID");grid.Columns.Add("Length","Length m");grid.Rows.Add("B1","3.75");var text=new TextBox{Text="Unchanged project",Dock=DockStyle.Top};var number=new NumericUpDown{Value=50,Dock=DockStyle.Top};var action=new Button{Text="Add entry",Dock=DockStyle.Top};int clicks=0;action.Click+=(s,e)=>clicks++;f.Controls.Add(grid);f.Controls.Add(text);f.Controls.Add(number);f.Controls.Add(action);PowTheme.Apply(f);DesktopAppearance.Attach(f);f.Show();Application.DoEvents();var row=grid.Rows[0];grid.CurrentCell=row.Cells[1];grid.BeginEdit(false);((TextBox)grid.EditingControl).Text="4.125";
   foreach(var mode in new[]{AppearanceMode.Dark,AppearanceMode.Light,AppearanceMode.Dark,AppearanceMode.Light}){DesktopAppearance.Select(mode);Check(DesktopAppearance.Palette.Dark==(mode==AppearanceMode.Dark),"Explicit mode applies");Check(AppearancePreferences.Read(DesktopAppearance.StoragePath)==mode,"Mode saved outside installation");Check(grid.Rows[0]==row&&grid.Rows.Count==1&&grid.CurrentCell==row.Cells[1],"Theme keeps grid row, order and selection");Check(grid.EditingControl!=null&&((TextBox)grid.EditingControl).Text=="4.125","Theme preserves an in-progress grid edit");Check(text.Text=="Unchanged project"&&number.Value==50,"Theme keeps input values");Check(grid.BackgroundColor==ModernUi.Surface&&text.BackColor==ModernUi.Input,"Existing controls repaint");}
   action.PerformClick();Check(clicks==1,"Theme switches do not duplicate event handlers");grid.EndEdit();DesktopAppearance.Select(AppearanceMode.System);systemLight=false;DesktopAppearance.RefreshSystemTheme();Check(DesktopAppearance.Palette.Dark,"System mode follows a Windows appearance change");DesktopAppearance.Select(AppearanceMode.Light);systemLight=false;DesktopAppearance.RefreshSystemTheme();Check(!DesktopAppearance.Palette.Dark,"Explicit Light stays light after a system event");f.Close();
  }
  using(var launcher=new LauncherForm()){Check(Find(launcher,"Workspace settings"),"Appearance is accessible from Workspaces");}
  Console.WriteLine("PASS: "+checks+" native appearance repaint, edit preservation and system-mode integration checks");
 }finally{if(Directory.Exists(dir))Directory.Delete(dir,true);}}
 static bool Find(Control c,string text){return c.Text==text||c.Controls.Cast<Control>().Any(child=>Find(child,text));}
}
